sys_variable_value.value:
(function execute(inputs, outputs) {

    var approval = new GlideRecord('sysapproval_approver');
    approval.addQuery('sysapproval', inputs.enrollment);
    approval.addQuery('state', 'requested');
    approval.query();

    var skippedCount = 0;

    while (approval.next()) {
        approval.state = 'skipped';
        approval.comments = 'Approval automatically skipped because this enrollment was manually approved by a Training Administrator.';
        approval.update();
        skippedCount++;
    }

    outputs.skippedApprovals = skippedCount;

})(inputs, outputs);

